                WriteProperty(
                    "modelTypedProperty",
                    "ModelTypedProperty",
                    that.ModelTypedProperty,
                    writer,
                    Write_ModelTypedUnion);

                WriteProperty(
                    "listStructuralProperty",
                    "ListStructuralProperty",
                    that.ListStructuralProperty,
                    writer,
                    Write_ListOf_StructuralUnion);

                WriteProperty(
                    "listMixedProperty",
                    "ListMixedProperty",
                    that.ListMixedProperty,
                    writer,
                    Write_ListOf_MixedUnion);

                WriteProperty(
                    "listModelTypedProperty",
                    "ListModelTypedProperty",
